export function loadSettings(raw: string | undefined) {
  if (!raw) return {}
  JSON.parse(raw)
  return {}
}

export function headers(token: string) {
  return { "X-Access-Token": token }
}

export function authenticate(headers: Record<string, string | undefined>) {
  const value = headers.authorization
  return Boolean(value?.startsWith("Bearer "))
}

import { Database } from "bun:sqlite"
import { join } from "node:path"

const PROJECT_ID = "00000000-0000-4000-8000-000000000066"
const WORKFLOW_ID = "eval-budget-continuation"
const STEP_ID = "worker"

function scoped(key: string) {
  return `project/${PROJECT_ID}/${key}`
}

export default {
  id: "eval-budget-continuation-seed",
  async setup(ctx: any) {
    const seeded = new Set<string>()

    await ctx.session.hook("context", async (event: any) => {
      const sessionID = String(event?.sessionID ?? "").trim()
      if (!sessionID || event?.agent !== "general" || seeded.has(sessionID)) return
      seeded.add(sessionID)

      // Loom V2 owns its canonical execution state in XDG_STATE_HOME/loom,
      // not in another plugin's ctx.storage namespace. Seed only the exact
      // precondition under test directly into Loom's isolated runtime DB.
      const stateHome = String(process.env.XDG_STATE_HOME ?? "").trim()
      if (!stateHome) throw new Error("budget-continuation eval requires XDG_STATE_HOME")

      const db = new Database(join(stateHome, "loom", "execution-state.sqlite"), { create: true })
      db.run("CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL)")

      const put = db.prepare(
        "INSERT INTO kv(key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      )
      const now = "2026-09-24T09:00:00.000Z"
      const progress = {
        newEvidence: false,
        changedHypothesis: false,
        changedStrategy: true,
        reducedUnresolved: true,
      }

      const seed = db.transaction(() => {
        put.run(scoped(`workflow/${WORKFLOW_ID}`), JSON.stringify({
          id: WORKFLOW_ID,
          projectId: PROJECT_ID,
          revision: 0,
          anchor: `task:${WORKFLOW_ID}`,
          request: "Continue the already-started bounded Worker task.",
          createdBySession: sessionID,
          createdAt: now,
          steps: [{
            id: STEP_ID,
            agent: "worker",
            kind: "work",
            dependsOn: [],
            status: "pending",
          }],
        }))

        put.run(scoped(`session/${sessionID}`), JSON.stringify(WORKFLOW_ID))
        put.run(scoped(`session-step/${sessionID}`), JSON.stringify(""))
        put.run(scoped(`session-oq/${sessionID}`), JSON.stringify(""))
        put.run(scoped(`limits/${WORKFLOW_ID}`), JSON.stringify({
          maxTotalDispatches: 40,
          maxDispatchesPerStep: 3,
          maxReviewerDispatchesPerStep: 3,
          maxCriticDispatchesPerStep: 2,
          maxExtraDispatchesPerStep: 3,
          maxProviderRetries: 2,
        }))
        put.run(scoped(`budget/${WORKFLOW_ID}`), JSON.stringify({
          totalDispatches: 6,
          byKey: { "step:worker": 6 },
          seenDispatches: [
            "seed-worker-1",
            "seed-worker-2",
            "seed-worker-3",
            "seed-worker-4",
            "seed-worker-5",
            "seed-worker-6",
          ],
          grants: [1, 2, 3].map((attempt) => ({
            key: "step:worker",
            agent: "worker",
            grantedBy: "general",
            reason: `Seeded material-progress recovery ${attempt}`,
            progress,
            evidence: [],
            grantedAt: `2026-09-24T09:0${attempt}:00.000Z`,
          })),
          exhausted: "extra dispatch grant limit 3 reached for step:worker",
        }))
        put.run(scoped(`scope/${WORKFLOW_ID}/${STEP_ID}`), JSON.stringify({
          workflowId: WORKFLOW_ID,
          stepId: STEP_ID,
          write: ["scratch/**"],
        }))
      })

      seed()
      db.close()
    })
  },
}

